'use strict';
const briefingSeen=[false,false,false];
const questBriefings=[
 {role:'시간 여행 데이터 탐정',title:'별빛 갑판에 도착한 의뢰',story:'1912년의 타이타닉을 살펴보는 기록 여행. 기록관 레오가 낡은 승객 명단을 건넸어요. 승객들의 특징과 생존 기록 사이에는 어떤 관계가 있을까요?',problem:'그런데 명단 곳곳에 나이가 빠져 있어요. 빈칸을 정리한 뒤 컴퓨터와 함께 기록의 규칙을 찾아야 해요.',goal:'모델을 학습·평가한 뒤 새 승객 두 명의 생존 확률을 직접 예측하고 비교하기',first:'승객 다섯 명의 기록부터 펼쳐봐요.'},
 {role:'백화점 마케팅 팀의 새 동료',title:'다음 VIP를 찾는 초대장',story:'백화점이 문을 닫을 무렵, 매니저 유나가 내일의 초대 행사 준비를 부탁했어요. 어떤 손님이 다음 기간에 VIP가 될지 지난 구매와 방문 기록에서 단서를 찾아요.',problem:'구매 금액이 빠진 칸도 있고, 금액과 방문 횟수는 숫자의 크기가 달라요. 비교하기 좋게 정리하는 일이 먼저예요.',goal:'새 고객 기록의 VIP 여부를 예상하고 실제 정답과 비교하기',first:'고객 다섯 분이 남긴 발자취를 읽어봐요.'},
 {role:'도시의 이동 시간을 연구하는 탐험가',title:'비 오는 밤, 도착 시간을 부탁해',story:'야간 차고의 엔지니어 준이 새 내비게이션을 준비하고 있어요. 목적지까지 몇 분이 걸릴지 알려주려면, 지난 이동 거리와 출발 시간의 기록이 필요해요.',problem:'이동 거리가 비거나 마이너스로 적힌 기록이 섞여 있어요. 먼저 기록을 정리하고, 거리와 시간 사이의 규칙을 찾아요.',goal:'도착까지 걸리는 시간을 예상하고 실제와 몇 분 차이 나는지 확인하기',first:'지난 다섯 번의 이동 일지를 펼쳐봐요.'}
];
const storyLessons=[
 [
  [['npc','나이가 빠진 승객을 모두 지우면 소중한 기록도 잃게 돼요. 계산을 이어갈 방법이 있을까요?'],['lumi','공부에 쓸 기록의 평균 나이를 빈칸에 넣어보자. 이게 결측치 처리야. 실제 나이를 알아낸 건 아니니 기억해줘!'],['lumi','성별처럼 글자로 된 항목은 종류별로 0과 1 표시를 붙일게. 컴퓨터가 읽기 위한 범주형 데이터 변환이지.']],
  [['npc','명단 정리가 끝났어요. 이제 승객의 특징과 생존 여부를 함께 살펴봐요.'],['lumi','열 묶음 중 여덟 묶음으로 공부하고 두 묶음은 봉인해두자. 나중에 실력을 확인할 새 문제야. 이게 학습·평가 데이터 분할이야.'],['lumi','여러 결정 나무가 함께 판단하는 랜덤 포레스트로 규칙을 배울게. 생존 또는 비생존처럼 종류를 고르는 건 분류라고 해.']],
  [['npc','봉인했던 승객 기록을 열 시간이에요. 공부할 때 보지 못한 기록도 맞힐까요?'],['lumi','먼저 생존 여부를 예상한 뒤 실제 정답과 비교하자. 서로 다른 기록도 있는지 살펴보자. 이런 대조가 모델 평가야.'],['lumi','우리는 학습용 가상 명단을 조사했어. 이 결과를 실제 역사 속 모든 사람에게 그대로 적용할 수는 없어.']]
 ],
 [
  [['npc','구매 금액이 비어 있네요. 기록을 비교하기 좋게 준비해주겠어요?'],['lumi','학습 기록의 평균으로 빈 금액을 채우자. 또 금액과 방문 횟수를 비슷한 눈금으로 맞출게. 이 과정을 표준화라고 해.'],['lumi','평균과 눈금은 공부할 기록에서만 구해. 나중에 확인할 기록을 미리 엿보면 공정한 평가가 아니니까!']],
  [['npc','준비한 기록으로 다음 기간의 VIP를 예상하는 연습을 해봐요.'],['lumi','입력은 지난 구매와 방문 기록, 정답은 다음 기간의 VIP 여부야. 이 둘의 관계를 배우는 거지.'],['lumi','일부 고객 기록은 남겨두고 로지스틱 회귀 분류 모델을 학습할게. 이름에 회귀가 있어도 여기서는 VIP인지 아닌지 분류해.']],
  [['npc','새 고객 기록을 펼쳤어요. 초대할 손님을 얼마나 잘 찾아냈을까요?'],['lumi','VIP라고 예상한 결과와 실제 정답을 비교해보자. 맞힌 비율인 정확도부터 볼게.'],['lumi','VIP를 놓쳤는지, 일반 고객을 VIP로 잘못 골랐는지도 중요해. 자세한 기록에서 정밀도와 재현율도 볼 수 있어.']]
 ],
 [
  [['npc','이동 거리가 빠졌거나 마이너스로 적힌 줄을 발견했어요. 그대로 계산해도 될까요?'],['lumi','마이너스 거리는 잘못된 기록이니 제거하자. 빈 거리는 공부할 기록의 평균으로 채울게. 데이터 정제는 이렇게 쓸 수 있는 기록을 준비하는 일이야.'],['lumi','요일처럼 글자로 적힌 종류도 숫자 표시로 바꿔줄게. 준비가 끝나면 도착 시간의 단서를 찾을 수 있어.']],
  [['npc','거리가 길거나 출발 시간대가 다르면 소요 시간도 달라질 수 있겠죠?'],['lumi','거리와 시간대 같은 특징을 입력으로, 실제 소요 시간을 정답으로 줄게. 몇 분처럼 숫자를 예상하는 문제는 회귀라고 해.'],['lumi','일부 이동 기록은 따로 남겨두고 랜덤 포레스트 회귀 모델로 공부하자. 새 길에서도 잘 예상하는지 확인해야 하니까.']],
  [['npc','이제 남겨둔 이동 기록으로 내비게이션의 예상 시간을 확인해요.'],['lumi','실제보다 일찍 예상해도 늦게 예상해도 차이가 있어. 그 차이의 크기를 평균 낸 것이 평균 절대 오차, MAE야.'],['lumi','평균 몇 분 어긋났는지 함께 읽어보자. 오차가 작을수록 이 확인 기록에서는 더 가까이 예상한 거야.']]
 ]
];
function showBriefing(){
 const b=questBriefings[current];stopDialogue();closeSceneWindow();
 const cover=document.createElement('section');cover.className='story-briefing';cover.id='story-briefing';cover.setAttribute('aria-label','모험 시작 안내');
 cover.innerHTML=`<div class="briefing-card"><img src="assets/lumi-portrait.png" alt="여우 탐정 루미"><span class="guide-label">CHAPTER 0${current+1} · 오늘의 의뢰</span><h2>${b.title}</h2><p>${b.story}</p><p>${b.problem}</p><div class="briefing-goal"><b>당신의 역할 · ${b.role}</b><p>${b.goal}</p></div><p class="briefing-route">기록 펼치기 → 빈칸 정리 → 규칙 배우기 → 결과 확인</p><p>루미와 함께 ${b.first}</p><small>학습용 가상 기록을 미리 분석한 결과로 진행해요. 모델을 즉석에서 학습하지는 않아요.</small><button class="primary" id="briefing-start">루미와 의뢰 시작하기 →</button></div>`;
 $('.game-scene').append(cover);
 $('#briefing-start').onclick=()=>{briefingSeen[current]=true;cover.remove();startStageStory(false);$('#dialogue-next').focus();};
 $('#briefing-start').focus();
}
